window.COURSE={"version": "TMK-2026.11.04-selfstudy-1", "title": "臺灣 TMK 產品知識基礎課", "modules": [{"id": 0, "title": "學習說明", "sceneIds": ["N00"], "pages": [], "duration": "2 分鐘", "video": "media/module-0-reviewed-v5.mp4", "poster": "media/module-0-reviewed-v5.jpg", "seconds": 42.9, "chapters": [{"id": "N00", "title": "怎麼學這門產品基礎課", "start": 0, "end": 42.9}], "captions": "media/module-0-reviewed-v5.vtt"}, {"id": 1, "title": "產品定位與學習價值", "sceneIds": ["N01", "N02"], "pages": [], "duration": "5–6 分鐘", "video": "media/module-1-reviewed-v5.mp4", "poster": "media/module-1-reviewed-v5.jpg", "seconds": 118.2, "chapters": [{"id": "N01", "title": "從家長問題理解產品", "start": 0, "end": 58.7}, {"id": "N02", "title": "從分餅乾看懂課程價值", "start": 58.7, "end": 118.2}], "captions": "media/module-1-reviewed-v5.vtt"}, {"id": 2, "title": "課程內容與分階概念", "sceneIds": ["N19", "N04", "N20", "N22"], "pages": [], "duration": "7–8 分鐘", "video": "media/module-2-reviewed-v5.mp4", "poster": "media/module-2-reviewed-v5.jpg", "seconds": 236.3, "chapters": [{"id": "N19", "title": "五類內容與九階的用途", "start": 0, "end": 49.6}, {"id": "N04", "title": "故事、操作與提問", "start": 49.6, "end": 100.30000000000001}, {"id": "N20", "title": "幼兒階段學什麼？與國小如何銜接", "start": 100.30000000000001, "end": 190.3}, {"id": "N22", "title": "九階不只安排內容，也培養學習習慣", "start": 190.3, "end": 236.3}], "captions": "media/module-2-reviewed-v5.vtt", "watchRevision": "coverage-reviewed-v5"}, {"id": 3, "title": "上課形式與正式課規格", "sceneIds": ["N06", "N05"], "pages": [], "duration": "5–6 分鐘", "video": "media/module-3-reviewed-v5.mp4", "poster": "media/module-3-reviewed-v5.jpg", "seconds": 119.1, "chapters": [{"id": "N06", "title": "正式課：人數、時間與頻率", "start": 0, "end": 46.4}, {"id": "N05", "title": "小舞臺：從一般上課到分享", "start": 46.4, "end": 119.1}], "captions": "media/module-3-reviewed-v5.vtt"}, {"id": 4, "title": "體驗課的基本安排", "sceneIds": ["N07", "N08", "N09"], "pages": [], "duration": "5–6 分鐘", "video": "media/module-4-reviewed-v5.mp4", "poster": "media/module-4-reviewed-v5.jpg", "seconds": 163.0, "chapters": [{"id": "N07", "title": "體驗人數依當次確認", "start": 0, "end": 50.2}, {"id": "N08", "title": "語言、課件與設備", "start": 50.2, "end": 111.30000000000001}, {"id": "N09", "title": "家長陪同看什麼", "start": 111.30000000000001, "end": 163.0}], "captions": "media/module-4-reviewed-v5.vtt"}, {"id": 5, "title": "學習資源與服務分工", "sceneIds": ["N10", "N11", "N12", "N03", "N21"], "pages": [], "duration": "9–11 分鐘", "video": "media/module-5-reviewed-v5.mp4", "poster": "media/module-5-reviewed-v5.jpg", "seconds": 305.7, "chapters": [{"id": "N10", "title": "依用途選學習資源", "start": 0, "end": 62.6}, {"id": "N11", "title": "體驗練習與回放", "start": 62.6, "end": 112.6}, {"id": "N12", "title": "三師分工與學習回饋", "start": 112.6, "end": 183.7}, {"id": "N03", "title": "觀察學習，不保證結果", "start": 183.7, "end": 239.7}, {"id": "N21", "title": "教材複習與學、練、測、評", "start": 239.7, "end": 305.7}], "captions": "media/module-5-reviewed-v5.vtt", "watchRevision": "coverage-reviewed-v5"}, {"id": 6, "title": "退費政策與資訊邊界", "sceneIds": ["N14", "N15"], "pages": [], "duration": "6–8 分鐘", "video": "media/module-6-reviewed-v5.mp4", "poster": "media/module-6-reviewed-v5.jpg", "seconds": 113.4, "chapters": [{"id": "N14", "title": "第四堂界線與退費計算", "start": 0, "end": 61.1}, {"id": "N15", "title": "哪些直接說，哪些要確認", "start": 61.1, "end": 113.4}], "captions": "media/module-6-reviewed-v5.vtt"}, {"id": 7, "title": "結課診斷與群組回報", "sceneIds": ["N17", "N18"], "pages": [], "duration": "10–15 分鐘", "video": "media/module-7-reviewed-v5.mp4", "poster": "media/module-7-reviewed-v5.jpg", "seconds": 113.0, "chapters": [{"id": "N17", "title": "產品知識診斷怎麼做", "start": 0, "end": 59.7}, {"id": "N18", "title": "把學習回報發到培訓群", "start": 59.7, "end": 113.0}], "captions": "media/module-7-reviewed-v5.vtt"}], "scenes": [{"id": "N00", "title": "怎麼學這門產品基礎課", "module": 0, "voice": "這門微課先幫你建立產品知識基礎。學完後，你要能說清課程是什麼、怎麼上課、有哪些支持，以及規則的適用範圍。每章先帶著問題看影片，再用自己的話回想。學員手冊每章選一到兩題重點填寫，其他題目可以口頭回答。看完影片並完成章內練習後，再前往下一章。最後獨立完成知識診斷，把學習回報貼到培訓群。培訓師會在後續答疑中確認理解。各階體驗課內容、約課流程和電話技巧，留到後面的專項培訓。", "paragraphs": ["這門微課先幫你建立產品知識基礎。學完後，你要能說清課程是什麼、怎麼上課、有哪些支持，以及規則的適用範圍。", "每章先帶著問題看影片，再用自己的話回想。學員手冊每章選一到兩題重點填寫，其他題目可以口頭回答。看完影片並完成章內練習後，再前往下一章。", "最後獨立完成知識診斷，把學習回報貼到培訓群。培訓師會在後續答疑中確認理解。各階體驗課內容、約課流程和電話技巧，留到後面的專項培訓。"], "duration": 42.9, "cues": [{"start": 0.1, "end": 3.984208, "text": "這門微課先幫你建立產品知識基礎。"}, {"start": 3.984208, "end": 5.102625, "text": "學完後，"}, {"start": 5.102625, "end": 9.247375, "text": "你要能說清課程是什麼、怎麼上課、有哪些支持，"}, {"start": 9.247375, "end": 11.839458, "text": "以及規則的適用範圍。"}, {"start": 11.839458, "end": 14.207875, "text": "每章先帶著問題看影片，"}, {"start": 14.207875, "end": 16.563166, "text": "再用自己的話回想。"}, {"start": 16.563166, "end": 19.747375, "text": "學員手冊每章選一到兩題重點填寫，"}, {"start": 19.747375, "end": 22.615791, "text": "其他題目可以口頭回答。"}, {"start": 22.615791, "end": 25.234208, "text": "看完影片並完成章內練習後，"}, {"start": 25.234208, "end": 27.273666, "text": "再前往下一章。"}, {"start": 27.273666, "end": 29.523666, "text": "最後獨立完成知識診斷，"}, {"start": 29.523666, "end": 32.510541, "text": "把學習回報貼到培訓群。"}, {"start": 32.510541, "end": 36.286833, "text": "培訓師會在後續答疑中確認理解。"}, {"start": 36.286833, "end": 39.852625, "text": "各階體驗課內容、約課流程和電話技巧，"}, {"start": 39.852625, "end": 42.9, "text": "留到後面的專項培訓。"}], "beats": [{"start": 0, "title": "產品知識基礎", "detail": ""}, {"start": 11.839458, "title": "看影片 → 回想 → 練習", "detail": ""}, {"start": 27.273666, "title": "自學 → 群內回報 → 培訓師答疑", "detail": ""}], "alignment": 1.0}, {"id": "N01", "title": "從家長問題理解產品", "module": 1, "voice": "家長接到電話，常會先問，你們到底上什麼？是不是讓孩子多算幾題？這門微課，就是幫你把這些基本問題說清楚。你是負責外撥邀約的TMK，需要了解產品，協助家長做好體驗準備。你不必分析每一道題，也不需要替孩子做完整學習規劃。但你要知道，我們希望孩子練習什麼、課怎麼上，以及體驗後有哪些支持。介紹課程時，可以這樣理解，孩子會接觸數學內容，也會練習看懂問題、找方法，並說出自己的想法。因此，不宜把這門課只說成刷題、搶先學進度，或保證考試成績進步。等一下每個單元，都會從家長真的會問的問題開始。學完後，你要能用自己的話回答，而不是把整段說明背下來。", "paragraphs": ["家長接到電話，常會先問，你們到底上什麼？是不是讓孩子多算幾題？這門微課，就是幫你把這些基本問題說清楚。", "你是負責外撥邀約的TMK，需要了解產品，協助家長做好體驗準備。你不必分析每一道題，也不需要替孩子做完整學習規劃。但你要知道，我們希望孩子練習什麼、課怎麼上，以及體驗後有哪些支持。", "介紹課程時，可以這樣理解，孩子會接觸數學內容，也會練習看懂問題、找方法，並說出自己的想法。因此，不宜把這門課只說成刷題、搶先學進度，或保證考試成績進步。", "等一下每個單元，都會從家長真的會問的問題開始。學完後，你要能用自己的話回答，而不是把整段說明背下來。"], "duration": 58.7, "cues": [{"start": 0.1, "end": 1.692125, "text": "家長接到電話，"}, {"start": 1.692125, "end": 2.863166, "text": "常會先問，"}, {"start": 2.863166, "end": 5.036833, "text": "你們到底上什麼？"}, {"start": 5.036833, "end": 7.957875, "text": "是不是讓孩子多算幾題？"}, {"start": 7.957875, "end": 9.15525, "text": "這門微課，"}, {"start": 9.15525, "end": 12.44475, "text": "就是幫你把這些基本問題說清楚。"}, {"start": 12.44475, "end": 14.642125, "text": "你是負責外撥邀約的TMK，"}, {"start": 14.642125, "end": 16.076333, "text": "需要了解產品，"}, {"start": 16.076333, "end": 19.010541, "text": "協助家長做好體驗準備。"}, {"start": 19.010541, "end": 20.94475, "text": "你不必分析每一道題，"}, {"start": 20.94475, "end": 24.313166, "text": "也不需要替孩子做完整學習規劃。"}, {"start": 24.313166, "end": 25.471041, "text": "但你要知道，"}, {"start": 25.471041, "end": 28.247375, "text": "我們希望孩子練習什麼、課怎麼上，"}, {"start": 28.247375, "end": 31.063166, "text": "以及體驗後有哪些支持。"}, {"start": 31.063166, "end": 32.339458, "text": "介紹課程時，"}, {"start": 32.339458, "end": 33.576333, "text": "可以這樣理解，"}, {"start": 33.576333, "end": 35.44475, "text": "孩子會接觸數學內容，"}, {"start": 35.44475, "end": 38.023666, "text": "也會練習看懂問題、找方法，"}, {"start": 38.023666, "end": 40.44475, "text": "並說出自己的想法。"}, {"start": 40.44475, "end": 41.378958, "text": "因此，"}, {"start": 41.378958, "end": 44.760541, "text": "不宜把這門課只說成刷題、搶先學進度，"}, {"start": 44.760541, "end": 47.484208, "text": "或保證考試成績進步。"}, {"start": 47.484208, "end": 49.023666, "text": "等一下每個單元，"}, {"start": 49.023666, "end": 52.378958, "text": "都會從家長真的會問的問題開始。"}, {"start": 52.378958, "end": 53.418416, "text": "學完後，"}, {"start": 53.418416, "end": 55.313166, "text": "你要能用自己的話回答，"}, {"start": 55.313166, "end": 58.7, "text": "而不是把整段說明背下來。"}], "beats": [{"start": 0, "title": "家長想知道什麼", "detail": ""}, {"start": 12.44475, "title": "產品知識的用途", "detail": ""}, {"start": 31.063166, "title": "看懂、找方法、說出想法", "detail": ""}, {"start": 47.484208, "title": "用自己的話解釋", "detail": ""}], "alignment": 1.0}, {"id": "N02", "title": "從分餅乾看懂課程價值", "module": 1, "voice": "例如，把六塊餅乾平均分給兩個人。孩子說每個人三塊，是得到答案。能說我輪流分，讓兩邊一樣多，就讓我們看見他的做法和理由。如果換成把六枝色筆放進兩個筆筒，孩子能不能試著運用相同想法？這就是我們介紹理解、方法、表達與應用時，可以使用的生活例子。這個例子用來幫你理解理念，不代表每一堂課都會使用相同題目。原教材依階段安排不同數學內容。TMK要知道內容會隨階段調整，不需要逐題教學，也不能只憑年齡就替孩子決定所有學習安排。向家長介紹時，先講一個具體行為就好。例如，我們也重視孩子能不能說出自己怎麼想。接著再依家長的問題補充，會比一次列出許多能力名稱更容易理解。", "paragraphs": ["例如，把六塊餅乾平均分給兩個人。孩子說每個人三塊，是得到答案。能說我輪流分，讓兩邊一樣多，就讓我們看見他的做法和理由。", "如果換成把六枝色筆放進兩個筆筒，孩子能不能試著運用相同想法？這就是我們介紹理解、方法、表達與應用時，可以使用的生活例子。這個例子用來幫你理解理念，不代表每一堂課都會使用相同題目。", "原教材依階段安排不同數學內容。TMK要知道內容會隨階段調整，不需要逐題教學，也不能只憑年齡就替孩子決定所有學習安排。", "向家長介紹時，先講一個具體行為就好。例如，我們也重視孩子能不能說出自己怎麼想。接著再依家長的問題補充，會比一次列出許多能力名稱更容易理解。"], "duration": 59.5, "cues": [{"start": 0.1, "end": 0.981583, "text": "例如，"}, {"start": 0.981583, "end": 4.19475, "text": "把六塊餅乾平均分給兩個人。"}, {"start": 4.19475, "end": 6.102625, "text": "孩子說每個人三塊，"}, {"start": 6.102625, "end": 8.102625, "text": "是得到答案。"}, {"start": 8.102625, "end": 9.497375, "text": "能說我輪流分，"}, {"start": 9.497375, "end": 10.721041, "text": "讓兩邊一樣多，"}, {"start": 10.721041, "end": 13.931583, "text": "就讓我們看見他的做法和理由。"}, {"start": 13.931583, "end": 16.90525, "text": "如果換成把六枝色筆放進兩個筆筒，"}, {"start": 16.90525, "end": 19.957875, "text": "孩子能不能試著運用相同想法？"}, {"start": 19.957875, "end": 23.918416, "text": "這就是我們介紹理解、方法、表達與應用時，"}, {"start": 23.918416, "end": 26.40525, "text": "可以使用的生活例子。"}, {"start": 26.40525, "end": 28.813166, "text": "這個例子用來幫你理解理念，"}, {"start": 28.813166, "end": 32.273666, "text": "不代表每一堂課都會使用相同題目。"}, {"start": 32.273666, "end": 35.984208, "text": "原教材依階段安排不同數學內容。"}, {"start": 35.984208, "end": 38.615791, "text": "TMK要知道內容會隨階段調整，"}, {"start": 38.615791, "end": 40.115791, "text": "不需要逐題教學，"}, {"start": 40.115791, "end": 44.339458, "text": "也不能只憑年齡就替孩子決定所有學習安排。"}, {"start": 44.339458, "end": 46.010541, "text": "向家長介紹時，"}, {"start": 46.010541, "end": 48.69475, "text": "先講一個具體行為就好。"}, {"start": 48.69475, "end": 49.602625, "text": "例如，"}, {"start": 49.602625, "end": 53.313166, "text": "我們也重視孩子能不能說出自己怎麼想。"}, {"start": 53.313166, "end": 55.326333, "text": "接著再依家長的問題補充，"}, {"start": 55.326333, "end": 59.5, "text": "會比一次列出許多能力名稱更容易理解。"}], "beats": [{"start": 0, "title": "六塊餅乾，平均分兩份", "detail": ""}, {"start": 13.931583, "title": "換成色筆，關係不變", "detail": ""}, {"start": 32.273666, "title": "內容依階段安排", "detail": ""}, {"start": 44.339458, "title": "具體行為比術語清楚", "detail": ""}], "alignment": 1.0}, {"id": "N19", "title": "五類內容與九階的用途", "module": 2, "voice": "課程內容包含數與代數、空間幾何、邏輯推理、生活應用與益智策略。例如數的組成、拼搭圖形、找規律、時間安排和有序規劃，都是理解內容方向的例子。不是每一階都以相同深度安排所有內容。九階呈現內容和方法的循序安排。故事提供問題，操作與圖片幫助觀察，老師提問讓孩子練習說明理由。這一階段知道設計用途即可，不要求背所有專業步驟。年齡和學習經驗可以提供了解孩子的資訊，但不能只憑年齡決定適合階段。個別安排交由對應人員進一步確認。各階體驗活動會在後續專項學習。", "paragraphs": ["課程內容包含數與代數、空間幾何、邏輯推理、生活應用與益智策略。例如數的組成、拼搭圖形、找規律、時間安排和有序規劃，都是理解內容方向的例子。不是每一階都以相同深度安排所有內容。", "九階呈現內容和方法的循序安排。故事提供問題，操作與圖片幫助觀察，老師提問讓孩子練習說明理由。這一階段知道設計用途即可，不要求背所有專業步驟。", "年齡和學習經驗可以提供了解孩子的資訊，但不能只憑年齡決定適合階段。個別安排交由對應人員進一步確認。各階體驗活動會在後續專項學習。"], "duration": 49.6, "cues": [{"start": 0.1, "end": 3.336833, "text": "課程內容包含數與代數、空間幾何、"}, {"start": 3.336833, "end": 7.168416, "text": "邏輯推理、生活應用與益智策略。"}, {"start": 7.168416, "end": 9.642125, "text": "例如數的組成、拼搭圖形、"}, {"start": 9.642125, "end": 12.642125, "text": "找規律、時間安排和有序規劃，"}, {"start": 12.642125, "end": 15.44475, "text": "都是理解內容方向的例子。"}, {"start": 15.44475, "end": 19.484208, "text": "不是每一階都以相同深度安排所有內容。"}, {"start": 19.484208, "end": 23.234208, "text": "九階呈現內容和方法的循序安排。"}, {"start": 23.234208, "end": 24.668416, "text": "故事提供問題，"}, {"start": 24.668416, "end": 26.615791, "text": "操作與圖片幫助觀察，"}, {"start": 26.615791, "end": 29.957875, "text": "老師提問讓孩子練習說明理由。"}, {"start": 29.957875, "end": 32.326333, "text": "這一階段知道設計用途即可，"}, {"start": 32.326333, "end": 34.997375, "text": "不要求背所有專業步驟。"}, {"start": 34.997375, "end": 38.471041, "text": "年齡和學習經驗可以提供了解孩子的資訊，"}, {"start": 38.471041, "end": 41.615791, "text": "但不能只憑年齡決定適合階段。"}, {"start": 41.615791, "end": 45.378958, "text": "個別安排交由對應人員進一步確認。"}, {"start": 45.378958, "end": 49.6, "text": "各階體驗活動會在後續專項學習。"}], "beats": [{"start": 0, "title": "五類內容，各有用途", "detail": ""}, {"start": 19.484208, "title": "九階循序安排", "detail": ""}, {"start": 34.997375, "title": "個別階段需要確認", "detail": ""}], "alignment": 1.0}, {"id": "N04", "title": "故事、操作與提問", "module": 2, "voice": "家長看到故事或操作畫面，可能會問，這是不是只是在玩遊戲？說明時，要把畫面連回孩子正在做的事情。情境讓孩子知道要解決什麼問題。操作讓他有機會試一試、比較結果。老師再透過提問，引導孩子說明自己的想法。重點不是畫面有多熱鬧，而是孩子有沒有在觀察、選擇、思考和表達。觀察課堂互動時，可以留意兩個地方，老師問了什麼？孩子怎麼回應，或做了什麼操作？再用一句話說明活動的用途。這是老師帶領的真人小班直播，不能因為畫面中有動畫，就把它說成孩子自己看錄播影片。", "paragraphs": ["家長看到故事或操作畫面，可能會問，這是不是只是在玩遊戲？說明時，要把畫面連回孩子正在做的事情。", "情境讓孩子知道要解決什麼問題。操作讓他有機會試一試、比較結果。老師再透過提問，引導孩子說明自己的想法。重點不是畫面有多熱鬧，而是孩子有沒有在觀察、選擇、思考和表達。", "觀察課堂互動時，可以留意兩個地方，老師問了什麼？孩子怎麼回應，或做了什麼操作？再用一句話說明活動的用途。", "這是老師帶領的真人小班直播，不能因為畫面中有動畫，就把它說成孩子自己看錄播影片。"], "duration": 50.7, "cues": [{"start": 0.1, "end": 2.547375, "text": "家長看到故事或操作畫面，"}, {"start": 2.547375, "end": 3.639458, "text": "可能會問，"}, {"start": 3.639458, "end": 6.260541, "text": "這是不是只是在玩遊戲？"}, {"start": 6.260541, "end": 7.352625, "text": "說明時，"}, {"start": 7.352625, "end": 10.971041, "text": "要把畫面連回孩子正在做的事情。"}, {"start": 10.971041, "end": 14.721041, "text": "情境讓孩子知道要解決什麼問題。"}, {"start": 14.721041, "end": 18.760541, "text": "操作讓他有機會試一試、比較結果。"}, {"start": 18.760541, "end": 20.55, "text": "老師再透過提問，"}, {"start": 20.55, "end": 23.418416, "text": "引導孩子說明自己的想法。"}, {"start": 23.418416, "end": 25.457875, "text": "重點不是畫面有多熱鬧，"}, {"start": 25.457875, "end": 30.471041, "text": "而是孩子有沒有在觀察、選擇、思考和表達。"}, {"start": 30.471041, "end": 32.19475, "text": "觀察課堂互動時，"}, {"start": 32.19475, "end": 33.65525, "text": "可以留意兩個地方，"}, {"start": 33.65525, "end": 35.589458, "text": "老師問了什麼？"}, {"start": 35.589458, "end": 37.05, "text": "孩子怎麼回應，"}, {"start": 37.05, "end": 39.286833, "text": "或做了什麼操作？"}, {"start": 39.286833, "end": 42.65525, "text": "再用一句話說明活動的用途。"}, {"start": 42.65525, "end": 44.957875, "text": "這是老師帶領的真人小班直播，"}, {"start": 44.957875, "end": 46.786833, "text": "不能因為畫面中有動畫，"}, {"start": 46.786833, "end": 50.7, "text": "就把它說成孩子自己看錄播影片。"}], "beats": [{"start": 0, "title": "遊戲畫面在做什麼", "detail": ""}, {"start": 10.971041, "title": "情境 → 操作 → 提問", "detail": ""}, {"start": 30.471041, "title": "觀察提問與回應", "detail": ""}, {"start": 42.65525, "title": "真人老師帶領", "detail": ""}], "alignment": 1.0}, {"id": "N06", "title": "正式課：人數、時間與頻率", "module": 3, "voice": "正式課一班幾個人，每次上多久？這兩項要分開記。先看人數。第一階和第二階，每班四到六人。第三階到第九階，每班六到八人。再看時間。第一階每堂三十到三十五分鐘。第二階到第九階，每堂四十到四十五分鐘。比較一下，第二階的人數和第一階相同，但是時間更長。第二階和第三階以後的時長相同，但人數不同。以上正式課都是每週兩次，採真人小班直播。這裡講的是正式課規格，不能拿來保證體驗課一定幾個人。", "paragraphs": ["正式課一班幾個人，每次上多久？這兩項要分開記。", "先看人數。第一階和第二階，每班四到六人。第三階到第九階，每班六到八人。", "再看時間。第一階每堂三十到三十五分鐘。第二階到第九階，每堂四十到四十五分鐘。", "比較一下，第二階的人數和第一階相同，但是時間更長。第二階和第三階以後的時長相同，但人數不同。", "以上正式課都是每週兩次，採真人小班直播。這裡講的是正式課規格，不能拿來保證體驗課一定幾個人。"], "duration": 46.4, "cues": [{"start": 0.1, "end": 1.85, "text": "正式課一班幾個人，"}, {"start": 1.85, "end": 3.892125, "text": "每次上多久？"}, {"start": 3.892125, "end": 6.484208, "text": "這兩項要分開記。"}, {"start": 6.484208, "end": 8.589458, "text": "先看人數。"}, {"start": 8.589458, "end": 10.102625, "text": "第一階和第二階，"}, {"start": 10.102625, "end": 12.326333, "text": "每班四到六人。"}, {"start": 12.326333, "end": 13.839458, "text": "第三階到第九階，"}, {"start": 13.839458, "end": 15.957875, "text": "每班六到八人。"}, {"start": 15.957875, "end": 17.878958, "text": "再看時間。"}, {"start": 17.878958, "end": 21.128958, "text": "第一階每堂三十到三十五分鐘。"}, {"start": 21.128958, "end": 22.668416, "text": "第二階到第九階，"}, {"start": 22.668416, "end": 25.313166, "text": "每堂四十到四十五分鐘。"}, {"start": 25.313166, "end": 26.471041, "text": "比較一下，"}, {"start": 26.471041, "end": 28.865791, "text": "第二階的人數和第一階相同，"}, {"start": 28.865791, "end": 31.076333, "text": "但是時間更長。"}, {"start": 31.076333, "end": 33.878958, "text": "第二階和第三階以後的時長相同，"}, {"start": 33.878958, "end": 35.94475, "text": "但人數不同。"}, {"start": 35.94475, "end": 38.3, "text": "以上正式課都是每週兩次，"}, {"start": 38.3, "end": 40.65525, "text": "採真人小班直播。"}, {"start": 40.65525, "end": 42.65525, "text": "這裡講的是正式課規格，"}, {"start": 42.65525, "end": 46.4, "text": "不能拿來保證體驗課一定幾個人。"}], "beats": [{"start": 0, "title": "正式課：先分人數和時間", "detail": ""}, {"start": 6.484208, "title": "班級人數", "detail": ""}, {"start": 15.957875, "title": "每堂時間", "detail": ""}, {"start": 25.313166, "title": "特別記住 S2", "detail": ""}, {"start": 35.94475, "title": "每週 2 次 · 真人小班直播", "detail": ""}], "alignment": 1.0}, {"id": "N05", "title": "小舞臺：從一般上課到分享", "module": 3, "voice": "小班上課，是不是孩子整堂課都會看到其他同學？這個問題要分成兩種情況。平常上課時，小朋友彼此看不到對方。畫面中的三個孩子代表不同的學員，這是互動機制示意，不是實際操作介面。到了互動環節，老師邀請一位孩子上小舞臺，準備分享自己的想法。請留意，這時候是受到邀請的孩子上臺，不是所有人一起公開畫面。開始分享時，其他同學才會看到這位孩子的畫面，聽到他的聲音。例如老師問，你是怎麼做的？孩子就可以說出自己的方法和理由。現在比較兩種狀態。一般上課，孩子彼此看不到。受邀上小舞臺分享時，同學能看見、聽見正在分享的孩子。所以，小班不等於整堂公開所有孩子的畫面，也不能說完全沒有同儕互動。暫停一下，請用自己的話回答，孩子什麼時候會被其他同學看見和聽見？", "paragraphs": ["小班上課，是不是孩子整堂課都會看到其他同學？這個問題要分成兩種情況。", "平常上課時，小朋友彼此看不到對方。畫面中的三個孩子代表不同的學員，這是互動機制示意，不是實際操作介面。", "到了互動環節，老師邀請一位孩子上小舞臺，準備分享自己的想法。請留意，這時候是受到邀請的孩子上臺，不是所有人一起公開畫面。", "開始分享時，其他同學才會看到這位孩子的畫面，聽到他的聲音。例如老師問，你是怎麼做的？孩子就可以說出自己的方法和理由。", "現在比較兩種狀態。一般上課，孩子彼此看不到。受邀上小舞臺分享時，同學能看見、聽見正在分享的孩子。", "所以，小班不等於整堂公開所有孩子的畫面，也不能說完全沒有同儕互動。暫停一下，請用自己的話回答，孩子什麼時候會被其他同學看見和聽見？"], "duration": 72.7, "cues": [{"start": 0.1, "end": 1.468416, "text": "小班上課，"}, {"start": 1.468416, "end": 5.234208, "text": "是不是孩子整堂課都會看到其他同學？"}, {"start": 5.234208, "end": 8.484208, "text": "這個問題要分成兩種情況。"}, {"start": 8.484208, "end": 9.957875, "text": "平常上課時，"}, {"start": 9.957875, "end": 12.707875, "text": "小朋友彼此看不到對方。"}, {"start": 12.707875, "end": 15.536833, "text": "畫面中的三個孩子代表不同的學員，"}, {"start": 15.536833, "end": 17.260541, "text": "這是互動機制示意，"}, {"start": 17.260541, "end": 19.734208, "text": "不是實際操作介面。"}, {"start": 19.734208, "end": 21.207875, "text": "到了互動環節，"}, {"start": 21.207875, "end": 23.576333, "text": "老師邀請一位孩子上小舞臺，"}, {"start": 23.576333, "end": 26.207875, "text": "準備分享自己的想法。"}, {"start": 26.207875, "end": 27.3, "text": "請留意，"}, {"start": 27.3, "end": 29.839458, "text": "這時候是受到邀請的孩子上臺，"}, {"start": 29.839458, "end": 32.852625, "text": "不是所有人一起公開畫面。"}, {"start": 32.852625, "end": 34.221041, "text": "開始分享時，"}, {"start": 34.221041, "end": 37.010541, "text": "其他同學才會看到這位孩子的畫面，"}, {"start": 37.010541, "end": 38.997375, "text": "聽到他的聲音。"}, {"start": 38.997375, "end": 40.3, "text": "例如老師問，"}, {"start": 40.3, "end": 42.378958, "text": "你是怎麼做的？"}, {"start": 42.378958, "end": 46.286833, "text": "孩子就可以說出自己的方法和理由。"}, {"start": 46.286833, "end": 49.05, "text": "現在比較兩種狀態。"}, {"start": 49.05, "end": 50.207875, "text": "一般上課，"}, {"start": 50.207875, "end": 52.497375, "text": "孩子彼此看不到。"}, {"start": 52.497375, "end": 54.510541, "text": "受邀上小舞臺分享時，"}, {"start": 54.510541, "end": 58.457875, "text": "同學能看見、聽見正在分享的孩子。"}, {"start": 58.457875, "end": 59.44475, "text": "所以，"}, {"start": 59.44475, "end": 62.392125, "text": "小班不等於整堂公開所有孩子的畫面，"}, {"start": 62.392125, "end": 65.457875, "text": "也不能說完全沒有同儕互動。"}, {"start": 65.457875, "end": 66.642125, "text": "暫停一下，"}, {"start": 66.642125, "end": 68.313166, "text": "請用自己的話回答，"}, {"start": 68.313166, "end": 72.7, "text": "孩子什麼時候會被其他同學看見和聽見？"}], "beats": [{"start": 0, "title": "整堂都看得到同學嗎？", "detail": ""}, {"start": 8.484208, "title": "一般上課：彼此看不到", "detail": ""}, {"start": 19.734208, "title": "老師邀請一位孩子上臺", "detail": ""}, {"start": 32.852625, "title": "開始分享：同學看見、聽見", "detail": ""}, {"start": 46.286833, "title": "比較兩種狀態", "detail": ""}, {"start": 58.457875, "title": "換你回答", "detail": ""}], "alignment": 1.0}, {"id": "N07", "title": "體驗人數依當次確認", "module": 4, "voice": "家長說，朋友上體驗課時只有兩個孩子，我們也會一樣嗎？不能用別人的一次經驗，保證這次的人數。體驗課人數，主要看當天選擇這個階段、這個時段的報名情況。因此不能承諾一定是一人、兩人、三人或四人，也不要直接套用正式課班級人數。可以確認的是，體驗課與正式課採相同的上課形式。家長能透過體驗，了解這種真人小班直播的上課方式，看看是否符合期待。但上課形式相同不等於所有規格相同，也不代表當天人數、內容、老師或其他安排都能照搬到未來的正式課。家長問到具體安排時，就依本次預約資訊確認。", "paragraphs": ["家長說，朋友上體驗課時只有兩個孩子，我們也會一樣嗎？不能用別人的一次經驗，保證這次的人數。", "體驗課人數，主要看當天選擇這個階段、這個時段的報名情況。因此不能承諾一定是一人、兩人、三人或四人，也不要直接套用正式課班級人數。", "可以確認的是，體驗課與正式課採相同的上課形式。家長能透過體驗，了解這種真人小班直播的上課方式，看看是否符合期待。", "但上課形式相同不等於所有規格相同，也不代表當天人數、內容、老師或其他安排都能照搬到未來的正式課。家長問到具體安排時，就依本次預約資訊確認。"], "duration": 50.2, "cues": [{"start": 0.1, "end": 1.086833, "text": "家長說，"}, {"start": 1.086833, "end": 3.560541, "text": "朋友上體驗課時只有兩個孩子，"}, {"start": 3.560541, "end": 5.471041, "text": "我們也會一樣嗎？"}, {"start": 5.471041, "end": 7.378958, "text": "不能用別人的一次經驗，"}, {"start": 7.378958, "end": 9.668416, "text": "保證這次的人數。"}, {"start": 9.668416, "end": 11.076333, "text": "體驗課人數，"}, {"start": 11.076333, "end": 15.707875, "text": "主要看當天選擇這個階段、這個時段的報名情況。"}, {"start": 15.707875, "end": 19.984208, "text": "因此不能承諾一定是一人、兩人、三人或四人，"}, {"start": 19.984208, "end": 23.3, "text": "也不要直接套用正式課班級人數。"}, {"start": 23.3, "end": 24.69475, "text": "可以確認的是，"}, {"start": 24.69475, "end": 28.378958, "text": "體驗課與正式課採相同的上課形式。"}, {"start": 28.378958, "end": 30.128958, "text": "家長能透過體驗，"}, {"start": 30.128958, "end": 32.852625, "text": "了解這種真人小班直播的上課方式，"}, {"start": 32.852625, "end": 35.378958, "text": "看看是否符合期待。"}, {"start": 35.378958, "end": 38.40525, "text": "但上課形式相同不等於所有規格相同，"}, {"start": 38.40525, "end": 40.878958, "text": "也不代表當天人數、內容、"}, {"start": 40.878958, "end": 44.94475, "text": "老師或其他安排都能照搬到未來的正式課。"}, {"start": 44.94475, "end": 46.918416, "text": "家長問到具體安排時，"}, {"start": 46.918416, "end": 50.2, "text": "就依本次預約資訊確認。"}], "beats": [{"start": 0, "title": "一次經驗不等於保證", "detail": ""}, {"start": 9.668416, "title": "階段、時段與當天報名", "detail": ""}, {"start": 23.3, "title": "上課形式相同", "detail": ""}, {"start": 35.378958, "title": "形式相同不等於所有規格相同", "detail": ""}], "alignment": 1.0}, {"id": "N08", "title": "語言、課件與設備", "module": 4, "voice": "在臺灣地區，家長可選中文授課，搭配繁體課件。也可選英文授課，搭配英文課件。先確認家長想選哪一種，不要只問要中文教材還是英文教材，因為授課語言也不同。上課使用VIPThink學生端。手機、平板和筆電皆可，依家中哪個設備方便使用來安排。設備可以使用，和已經完成上課準備，是兩件不同的事。預約後，還需要確認家長知道使用哪個App，以及帳號和登入方式。具體安裝與登入步驟，要依現行操作指引說明，不臨時猜測。你可以用兩個問題確認，您希望選中文授課還是英文授課？以及家裡準備用手機、平板，還是筆電上課？這些問題是為了確認體驗安排，不是替孩子判定適合哪一種語言課程。", "paragraphs": ["在臺灣地區，家長可選中文授課，搭配繁體課件。也可選英文授課，搭配英文課件。先確認家長想選哪一種，不要只問要中文教材還是英文教材，因為授課語言也不同。", "上課使用VIPThink學生端。手機、平板和筆電皆可，依家中哪個設備方便使用來安排。設備可以使用，和已經完成上課準備，是兩件不同的事。", "預約後，還需要確認家長知道使用哪個App，以及帳號和登入方式。具體安裝與登入步驟，要依現行操作指引說明，不臨時猜測。", "你可以用兩個問題確認，您希望選中文授課還是英文授課？以及家裡準備用手機、平板，還是筆電上課？這些問題是為了確認體驗安排，不是替孩子判定適合哪一種語言課程。"], "duration": 61.1, "cues": [{"start": 0.1, "end": 1.310541, "text": "在臺灣地區，"}, {"start": 1.310541, "end": 3.126333, "text": "家長可選中文授課，"}, {"start": 3.126333, "end": 5.392125, "text": "搭配繁體課件。"}, {"start": 5.392125, "end": 7.036833, "text": "也可選英文授課，"}, {"start": 7.036833, "end": 9.221041, "text": "搭配英文課件。"}, {"start": 9.221041, "end": 11.40525, "text": "先確認家長想選哪一種，"}, {"start": 11.40525, "end": 14.221041, "text": "不要只問要中文教材還是英文教材，"}, {"start": 14.221041, "end": 16.852625, "text": "因為授課語言也不同。"}, {"start": 16.852625, "end": 19.957875, "text": "上課使用VIPThink學生端。"}, {"start": 19.957875, "end": 22.628958, "text": "手機、平板和筆電皆可，"}, {"start": 22.628958, "end": 26.023666, "text": "依家中哪個設備方便使用來安排。"}, {"start": 26.023666, "end": 27.55, "text": "設備可以使用，"}, {"start": 27.55, "end": 29.44475, "text": "和已經完成上課準備，"}, {"start": 29.44475, "end": 31.707875, "text": "是兩件不同的事。"}, {"start": 31.707875, "end": 32.69475, "text": "預約後，"}, {"start": 32.69475, "end": 35.023666, "text": "還需要確認家長知道使用哪個App，"}, {"start": 35.023666, "end": 37.8, "text": "以及帳號和登入方式。"}, {"start": 37.8, "end": 39.826333, "text": "具體安裝與登入步驟，"}, {"start": 39.826333, "end": 41.786833, "text": "要依現行操作指引說明，"}, {"start": 41.786833, "end": 43.786833, "text": "不臨時猜測。"}, {"start": 43.786833, "end": 45.984208, "text": "你可以用兩個問題確認，"}, {"start": 45.984208, "end": 49.55, "text": "您希望選中文授課還是英文授課？"}, {"start": 49.55, "end": 52.168416, "text": "以及家裡準備用手機、平板，"}, {"start": 52.168416, "end": 54.3, "text": "還是筆電上課？"}, {"start": 54.3, "end": 56.878958, "text": "這些問題是為了確認體驗安排，"}, {"start": 56.878958, "end": 61.1, "text": "不是替孩子判定適合哪一種語言課程。"}], "beats": [{"start": 0, "title": "語言與課件成對確認", "detail": ""}, {"start": 16.852625, "title": "三種設備皆可使用", "detail": ""}, {"start": 31.707875, "title": "確認學生端、帳號與登入", "detail": ""}, {"start": 43.786833, "title": "按需要確認體驗準備", "detail": ""}], "alignment": 1.0}, {"id": "N09", "title": "家長陪同看什麼", "module": 4, "voice": "體驗課一定要家長陪嗎？我們建議家長陪同，讓家長自己了解課程形式，也觀察孩子的參與情形。陪同時，可以留意老師怎麼帶活動，孩子怎麼回應、怎麼操作，或怎麼說自己的想法。這樣上完課後，家長比較能判斷這是不是自己期待的課程型態，而不只是聽我們介紹。陪同也是一段親子共學時間。可以鼓勵孩子試著回應，讓他有自己思考與表達的機會，不需要急著替孩子回答每個問題。預約前，你要說清楚人數安排、上課形式、語言選擇、設備與App，以及建議家長陪同的原因。已確認的就直接說，還沒確認的就先核對，不用用猜測把答案補滿。", "paragraphs": ["體驗課一定要家長陪嗎？我們建議家長陪同，讓家長自己了解課程形式，也觀察孩子的參與情形。", "陪同時，可以留意老師怎麼帶活動，孩子怎麼回應、怎麼操作，或怎麼說自己的想法。這樣上完課後，家長比較能判斷這是不是自己期待的課程型態，而不只是聽我們介紹。", "陪同也是一段親子共學時間。可以鼓勵孩子試著回應，讓他有自己思考與表達的機會，不需要急著替孩子回答每個問題。", "預約前，你要說清楚人數安排、上課形式、語言選擇、設備與App，以及建議家長陪同的原因。已確認的就直接說，還沒確認的就先核對，不用用猜測把答案補滿。"], "duration": 51.7, "cues": [{"start": 0.1, "end": 2.90525, "text": "體驗課一定要家長陪嗎？"}, {"start": 2.90525, "end": 4.615791, "text": "我們建議家長陪同，"}, {"start": 4.615791, "end": 7.023666, "text": "讓家長自己了解課程形式，"}, {"start": 7.023666, "end": 9.852625, "text": "也觀察孩子的參與情形。"}, {"start": 9.852625, "end": 10.865791, "text": "陪同時，"}, {"start": 10.865791, "end": 12.931583, "text": "可以留意老師怎麼帶活動，"}, {"start": 12.931583, "end": 15.247375, "text": "孩子怎麼回應、怎麼操作，"}, {"start": 15.247375, "end": 17.747375, "text": "或怎麼說自己的想法。"}, {"start": 17.747375, "end": 19.19475, "text": "這樣上完課後，"}, {"start": 19.19475, "end": 22.721041, "text": "家長比較能判斷這是不是自己期待的課程型態，"}, {"start": 22.721041, "end": 25.247375, "text": "而不只是聽我們介紹。"}, {"start": 25.247375, "end": 28.576333, "text": "陪同也是一段親子共學時間。"}, {"start": 28.576333, "end": 30.563166, "text": "可以鼓勵孩子試著回應，"}, {"start": 30.563166, "end": 32.997375, "text": "讓他有自己思考與表達的機會，"}, {"start": 32.997375, "end": 36.286833, "text": "不需要急著替孩子回答每個問題。"}, {"start": 36.286833, "end": 37.247375, "text": "預約前，"}, {"start": 37.247375, "end": 40.471041, "text": "你要說清楚人數安排、上課形式、"}, {"start": 40.471041, "end": 42.44475, "text": "語言選擇、設備與App，"}, {"start": 42.44475, "end": 45.142125, "text": "以及建議家長陪同的原因。"}, {"start": 45.142125, "end": 46.734208, "text": "已確認的就直接說，"}, {"start": 46.734208, "end": 48.510541, "text": "還沒確認的就先核對，"}, {"start": 48.510541, "end": 51.7, "text": "不用用猜測把答案補滿。"}], "beats": [{"start": 0, "title": "建議家長陪同", "detail": ""}, {"start": 9.852625, "title": "觀察引導與孩子參與", "detail": ""}, {"start": 25.247375, "title": "給孩子自己回應的空間", "detail": ""}, {"start": 36.286833, "title": "已確認資訊與待確認安排", "detail": ""}], "alignment": 1.0}, {"id": "N10", "title": "依用途選學習資源", "module": 5, "voice": "家長問，下課後還能複習嗎？回答前，先分清楚他想複習什麼。課程提供的資源包括課前預習、重點影片、小老師影片和課程回放。預習讓孩子先熟悉故事與任務。重點影片用來回顧學習內容。小老師影片讓孩子試著說出自己的做法。課程回放則可以再看當堂上課的過程。所以，想回看當天老師和孩子的互動，應想到課程回放。想讓孩子說明做法，要理解小老師影片的用途。這些資源各有用途，不能全部混稱為回放，也不能說它們可以取代真人直播課。使用這些資源時，先想要做什麼，再對照名稱。各項資源是否開通、能看多久，仍需對照實際方案。接下來，我們會單獨整理已確認的體驗課服務。", "paragraphs": ["家長問，下課後還能複習嗎？回答前，先分清楚他想複習什麼。", "課程提供的資源包括課前預習、重點影片、小老師影片和課程回放。預習讓孩子先熟悉故事與任務。重點影片用來回顧學習內容。小老師影片讓孩子試著說出自己的做法。課程回放則可以再看當堂上課的過程。", "所以，想回看當天老師和孩子的互動，應想到課程回放。想讓孩子說明做法，要理解小老師影片的用途。這些資源各有用途，不能全部混稱為回放，也不能說它們可以取代真人直播課。", "使用這些資源時，先想要做什麼，再對照名稱。各項資源是否開通、能看多久，仍需對照實際方案。接下來，我們會單獨整理已確認的體驗課服務。"], "duration": 62.6, "cues": [{"start": 0.1, "end": 1.257875, "text": "家長問，"}, {"start": 1.257875, "end": 3.668416, "text": "下課後還能複習嗎？"}, {"start": 3.668416, "end": 4.668416, "text": "回答前，"}, {"start": 4.668416, "end": 7.471041, "text": "先分清楚他想複習什麼。"}, {"start": 7.471041, "end": 10.247375, "text": "課程提供的資源包括課前預習、"}, {"start": 10.247375, "end": 14.484208, "text": "重點影片、小老師影片和課程回放。"}, {"start": 14.484208, "end": 17.997375, "text": "預習讓孩子先熟悉故事與任務。"}, {"start": 17.997375, "end": 21.510541, "text": "重點影片用來回顧學習內容。"}, {"start": 21.510541, "end": 25.628958, "text": "小老師影片讓孩子試著說出自己的做法。"}, {"start": 25.628958, "end": 29.576333, "text": "課程回放則可以再看當堂上課的過程。"}, {"start": 29.576333, "end": 30.563166, "text": "所以，"}, {"start": 30.563166, "end": 33.063166, "text": "想回看當天老師和孩子的互動，"}, {"start": 33.063166, "end": 35.431583, "text": "應想到課程回放。"}, {"start": 35.431583, "end": 37.234208, "text": "想讓孩子說明做法，"}, {"start": 37.234208, "end": 40.286833, "text": "要理解小老師影片的用途。"}, {"start": 40.286833, "end": 42.15525, "text": "這些資源各有用途，"}, {"start": 42.15525, "end": 43.931583, "text": "不能全部混稱為回放，"}, {"start": 43.931583, "end": 47.181583, "text": "也不能說它們可以取代真人直播課。"}, {"start": 47.181583, "end": 48.852625, "text": "使用這些資源時，"}, {"start": 48.852625, "end": 50.128958, "text": "先想要做什麼，"}, {"start": 50.128958, "end": 52.036833, "text": "再對照名稱。"}, {"start": 52.036833, "end": 54.918416, "text": "各項資源是否開通、能看多久，"}, {"start": 54.918416, "end": 57.392125, "text": "仍需對照實際方案。"}, {"start": 57.392125, "end": 58.457875, "text": "接下來，"}, {"start": 58.457875, "end": 62.6, "text": "我們會單獨整理已確認的體驗課服務。"}], "beats": [{"start": 0, "title": "先問想複習什麼", "detail": ""}, {"start": 7.471041, "title": "課前預習與課後資源", "detail": ""}, {"start": 29.576333, "title": "按需要選資源", "detail": ""}, {"start": 47.181583, "title": "期限與開通需核對", "detail": ""}], "alignment": 1.0}, {"id": "N11", "title": "體驗練習與回放", "module": 5, "voice": "體驗課結束後，也提供線上課後鞏固練習。練習對應課程的三個環節，每個環節兩道題，合計約六題。介紹時，可以說，上完體驗課，孩子還可以透過線上練習，再回顧當堂內容。不要把這些題目說成能力診斷，也不用承諾做完就一定掌握所有內容。體驗課也支援觀看課程回放，有效期是一百八十天。家長想再看當天的互動，可以使用這項服務。請特別記住，一百八十天是這裡已確認的體驗課回放期限，不代表所有正式課方案或其他資源都一樣。當家長問其他資源的觀看期限，應核對該方案，不能直接沿用這個數字。", "paragraphs": ["體驗課結束後，也提供線上課後鞏固練習。練習對應課程的三個環節，每個環節兩道題，合計約六題。", "介紹時，可以說，上完體驗課，孩子還可以透過線上練習，再回顧當堂內容。不要把這些題目說成能力診斷，也不用承諾做完就一定掌握所有內容。", "體驗課也支援觀看課程回放，有效期是一百八十天。家長想再看當天的互動，可以使用這項服務。", "請特別記住，一百八十天是這裡已確認的體驗課回放期限，不代表所有正式課方案或其他資源都一樣。當家長問其他資源的觀看期限，應核對該方案，不能直接沿用這個數字。"], "duration": 50.0, "cues": [{"start": 0.1, "end": 1.6, "text": "體驗課結束後，"}, {"start": 1.6, "end": 4.839458, "text": "也提供線上課後鞏固練習。"}, {"start": 4.839458, "end": 7.128958, "text": "練習對應課程的三個環節，"}, {"start": 7.128958, "end": 8.589458, "text": "每個環節兩道題，"}, {"start": 8.589458, "end": 10.760541, "text": "合計約六題。"}, {"start": 10.760541, "end": 11.747375, "text": "介紹時，"}, {"start": 11.747375, "end": 12.576333, "text": "可以說，"}, {"start": 12.576333, "end": 13.826333, "text": "上完體驗課，"}, {"start": 13.826333, "end": 15.94475, "text": "孩子還可以透過線上練習，"}, {"start": 15.94475, "end": 18.352625, "text": "再回顧當堂內容。"}, {"start": 18.352625, "end": 20.865791, "text": "不要把這些題目說成能力診斷，"}, {"start": 20.865791, "end": 24.55, "text": "也不用承諾做完就一定掌握所有內容。"}, {"start": 24.55, "end": 27.260541, "text": "體驗課也支援觀看課程回放，"}, {"start": 27.260541, "end": 29.8, "text": "有效期是一百八十天。"}, {"start": 29.8, "end": 31.957875, "text": "家長想再看當天的互動，"}, {"start": 31.957875, "end": 34.313166, "text": "可以使用這項服務。"}, {"start": 34.313166, "end": 35.707875, "text": "請特別記住，"}, {"start": 35.707875, "end": 39.063166, "text": "一百八十天是這裡已確認的體驗課回放期限，"}, {"start": 39.063166, "end": 43.023666, "text": "不代表所有正式課方案或其他資源都一樣。"}, {"start": 43.023666, "end": 45.589458, "text": "當家長問其他資源的觀看期限，"}, {"start": 45.589458, "end": 46.90525, "text": "應核對該方案，"}, {"start": 46.90525, "end": 50.0, "text": "不能直接沿用這個數字。"}], "beats": [{"start": 0, "title": "3 個環節，每環節 2 題", "detail": ""}, {"start": 10.760541, "title": "練習用來回顧內容", "detail": ""}, {"start": 24.55, "title": "體驗課回放 180 天", "detail": ""}, {"start": 34.313166, "title": "期限不能擴大套用", "detail": ""}], "alignment": 1.0}, {"id": "N12", "title": "三師分工與學習回饋", "module": 5, "voice": "除了資源名稱，TMK也要知道，家長可能需要哪些協助。原教材介紹臺灣專屬師資，使用貼近臺灣本地的口音。這不等於對所有老師的國籍作保證。三師服務有不同分工，授課老師負責引導、提問及觀察課堂表現。班導師負責課程聯繫、學習追蹤與回饋。教研支援著重課程內容、學習路徑與教學支持。不是每個問題都找同一個角色，也不代表家長可以直接聯繫每一位教研人員。家長問孩子今天表現如何，要回到課堂參與、練習和老師回饋。家長問之後要怎麼安排，則需要進一步的方案或學習建議。你可以先把問題記清楚，再依團隊實際分工交接。不要因為看到一次練習結果，就替孩子下能力結論。這一單元要記住的，不是把所有功能一次念完，而是能回答，這項資源能幫家長或孩子做什麼？以及哪些服務已確認適用這次體驗？", "paragraphs": ["除了資源名稱，TMK也要知道，家長可能需要哪些協助。原教材介紹臺灣專屬師資，使用貼近臺灣本地的口音。這不等於對所有老師的國籍作保證。", "三師服務有不同分工，授課老師負責引導、提問及觀察課堂表現。班導師負責課程聯繫、學習追蹤與回饋。教研支援著重課程內容、學習路徑與教學支持。不是每個問題都找同一個角色，也不代表家長可以直接聯繫每一位教研人員。", "家長問孩子今天表現如何，要回到課堂參與、練習和老師回饋。家長問之後要怎麼安排，則需要進一步的方案或學習建議。", "你可以先把問題記清楚，再依團隊實際分工交接。不要因為看到一次練習結果，就替孩子下能力結論。", "這一單元要記住的，不是把所有功能一次念完，而是能回答，這項資源能幫家長或孩子做什麼？以及哪些服務已確認適用這次體驗？"], "duration": 71.1, "cues": [{"start": 0.1, "end": 1.49475, "text": "除了資源名稱，"}, {"start": 1.49475, "end": 2.823666, "text": "TMK也要知道，"}, {"start": 2.823666, "end": 5.563166, "text": "家長可能需要哪些協助。"}, {"start": 5.563166, "end": 7.878958, "text": "原教材介紹臺灣專屬師資，"}, {"start": 7.878958, "end": 10.734208, "text": "使用貼近臺灣本地的口音。"}, {"start": 10.734208, "end": 14.418416, "text": "這不等於對所有老師的國籍作保證。"}, {"start": 14.418416, "end": 16.313166, "text": "三師服務有不同分工，"}, {"start": 16.313166, "end": 20.826333, "text": "授課老師負責引導、提問及觀察課堂表現。"}, {"start": 20.826333, "end": 25.497375, "text": "班導師負責課程聯繫、學習追蹤與回饋。"}, {"start": 25.497375, "end": 30.576333, "text": "教研支援著重課程內容、學習路徑與教學支持。"}, {"start": 30.576333, "end": 33.15525, "text": "不是每個問題都找同一個角色，"}, {"start": 33.15525, "end": 37.260541, "text": "也不代表家長可以直接聯繫每一位教研人員。"}, {"start": 37.260541, "end": 39.642125, "text": "家長問孩子今天表現如何，"}, {"start": 39.642125, "end": 43.721041, "text": "要回到課堂參與、練習和老師回饋。"}, {"start": 43.721041, "end": 45.878958, "text": "家長問之後要怎麼安排，"}, {"start": 45.878958, "end": 49.247375, "text": "則需要進一步的方案或學習建議。"}, {"start": 49.247375, "end": 51.392125, "text": "你可以先把問題記清楚，"}, {"start": 51.392125, "end": 54.15525, "text": "再依團隊實際分工交接。"}, {"start": 54.15525, "end": 56.418416, "text": "不要因為看到一次練習結果，"}, {"start": 56.418416, "end": 58.984208, "text": "就替孩子下能力結論。"}, {"start": 58.984208, "end": 60.602625, "text": "這一單元要記住的，"}, {"start": 60.602625, "end": 62.523666, "text": "不是把所有功能一次念完，"}, {"start": 62.523666, "end": 63.734208, "text": "而是能回答，"}, {"start": 63.734208, "end": 67.05, "text": "這項資源能幫家長或孩子做什麼？"}, {"start": 67.05, "end": 71.1, "text": "以及哪些服務已確認適用這次體驗？"}], "beats": [{"start": 0, "title": "口音與國籍分開理解", "detail": ""}, {"start": 14.418416, "title": "三師分工", "detail": ""}, {"start": 37.260541, "title": "依問題找對應支持", "detail": ""}, {"start": 49.247375, "title": "綜合觀察，不急著下結論", "detail": ""}, {"start": 58.984208, "title": "用途與適用範圍", "detail": ""}], "alignment": 1.0}, {"id": "N03", "title": "觀察學習，不保證結果", "module": 5, "voice": "家長也會問，那怎麼知道孩子有沒有學到？我們可以建議他觀察具體表現，孩子能不能理解老師的問題？願不願意嘗試？能不能說明自己的做法？遇到不同問法時，又會怎麼想？一次答錯，不等於沒有學習。一次答對，也不代表已經熟練掌握。課堂回應、課後練習和老師的回饋，要放在一起看。所以，TMK可以說明課程提供的學習機會與觀察方向，不要承諾上幾堂一定會進步或每個孩子都會有相同成果。如果家長想深入了解孩子個別的學習情況，就記下具體問題，再依服務分工交接。暫停一下，用自己的話分清楚，課程重視的方向，和不能直接保證的結果。", "paragraphs": ["家長也會問，那怎麼知道孩子有沒有學到？我們可以建議他觀察具體表現，孩子能不能理解老師的問題？願不願意嘗試？能不能說明自己的做法？遇到不同問法時，又會怎麼想？", "一次答錯，不等於沒有學習。一次答對，也不代表已經熟練掌握。課堂回應、課後練習和老師的回饋，要放在一起看。", "所以，TMK可以說明課程提供的學習機會與觀察方向，不要承諾上幾堂一定會進步或每個孩子都會有相同成果。如果家長想深入了解孩子個別的學習情況，就記下具體問題，再依服務分工交接。", "暫停一下，用自己的話分清楚，課程重視的方向，和不能直接保證的結果。"], "duration": 56.0, "cues": [{"start": 0.1, "end": 1.468416, "text": "家長也會問，"}, {"start": 1.468416, "end": 4.510541, "text": "那怎麼知道孩子有沒有學到？"}, {"start": 4.510541, "end": 6.984208, "text": "我們可以建議他觀察具體表現，"}, {"start": 6.984208, "end": 9.918416, "text": "孩子能不能理解老師的問題？"}, {"start": 9.918416, "end": 12.181583, "text": "願不願意嘗試？"}, {"start": 12.181583, "end": 15.010541, "text": "能不能說明自己的做法？"}, {"start": 15.010541, "end": 16.602625, "text": "遇到不同問法時，"}, {"start": 16.602625, "end": 18.497375, "text": "又會怎麼想？"}, {"start": 18.497375, "end": 19.668416, "text": "一次答錯，"}, {"start": 19.668416, "end": 22.102625, "text": "不等於沒有學習。"}, {"start": 22.102625, "end": 23.260541, "text": "一次答對，"}, {"start": 23.260541, "end": 26.010541, "text": "也不代表已經熟練掌握。"}, {"start": 26.010541, "end": 29.431583, "text": "課堂回應、課後練習和老師的回饋，"}, {"start": 29.431583, "end": 31.510541, "text": "要放在一起看。"}, {"start": 31.510541, "end": 32.510541, "text": "所以，"}, {"start": 32.510541, "end": 36.115791, "text": "TMK可以說明課程提供的學習機會與觀察方向，"}, {"start": 36.115791, "end": 38.076333, "text": "不要承諾上幾堂一定會進步"}, {"start": 38.076333, "end": 41.142125, "text": "或每個孩子都會有相同成果。"}, {"start": 41.142125, "end": 44.457875, "text": "如果家長想深入了解孩子個別的學習情況，"}, {"start": 44.457875, "end": 46.063166, "text": "就記下具體問題，"}, {"start": 46.063166, "end": 48.418416, "text": "再依服務分工交接。"}, {"start": 48.418416, "end": 49.65525, "text": "暫停一下，"}, {"start": 49.65525, "end": 51.273666, "text": "用自己的話分清楚，"}, {"start": 51.273666, "end": 52.826333, "text": "課程重視的方向，"}, {"start": 52.826333, "end": 56.0, "text": "和不能直接保證的結果。"}], "beats": [{"start": 0, "title": "從具體表現觀察", "detail": ""}, {"start": 18.497375, "title": "一次答對不等於熟練", "detail": ""}, {"start": 31.510541, "title": "說明機會，保留效果界線", "detail": ""}, {"start": 48.418416, "title": "回想自己的理解", "detail": ""}], "alignment": 1.0}, {"id": "N14", "title": "第四堂界線與退費計算", "module": 6, "voice": "退費政策是TMK可以直接說明的資訊。第一，四堂課以內，可以全額退費。這裡的以內包含第四堂，所以剛上完第四堂，不是已經超過四堂。第二，超過四堂課，退費金額依公式計算，購買價格，除以基礎直播課堂數，再乘以剩餘堂數。我們用假設數字看一次。假設購買價格是一萬二千元，基礎直播課共四十堂，剩下三十堂。先用一萬二千除以四十，得到每堂三百元。再乘以剩餘三十堂，退費金額是九千元。這只是計算示例，不是實際課包或售價。實際說明要使用該筆訂單的資料。第三，退款會在七到十四個工作天內，退回原付款管道。工作天不能說成日曆天，也不要自行承諾隔天入帳。", "paragraphs": ["退費政策是TMK可以直接說明的資訊。第一，四堂課以內，可以全額退費。這裡的以內包含第四堂，所以剛上完第四堂，不是已經超過四堂。", "第二，超過四堂課，退費金額依公式計算，購買價格，除以基礎直播課堂數，再乘以剩餘堂數。", "我們用假設數字看一次。假設購買價格是一萬二千元，基礎直播課共四十堂，剩下三十堂。先用一萬二千除以四十，得到每堂三百元。再乘以剩餘三十堂，退費金額是九千元。這只是計算示例，不是實際課包或售價。實際說明要使用該筆訂單的資料。", "第三，退款會在七到十四個工作天內，退回原付款管道。工作天不能說成日曆天，也不要自行承諾隔天入帳。"], "duration": 61.1, "cues": [{"start": 0.1, "end": 4.063166, "text": "退費政策是TMK可以直接說明的資訊。"}, {"start": 4.063166, "end": 4.760541, "text": "第一，"}, {"start": 4.760541, "end": 6.063166, "text": "四堂課以內，"}, {"start": 6.063166, "end": 8.15525, "text": "可以全額退費。"}, {"start": 8.15525, "end": 10.181583, "text": "這裡的以內包含第四堂，"}, {"start": 10.181583, "end": 11.813166, "text": "所以剛上完第四堂，"}, {"start": 11.813166, "end": 14.260541, "text": "不是已經超過四堂。"}, {"start": 14.260541, "end": 14.878958, "text": "第二，"}, {"start": 14.878958, "end": 16.207875, "text": "超過四堂課，"}, {"start": 16.207875, "end": 18.063166, "text": "退費金額依公式計算，"}, {"start": 18.063166, "end": 19.076333, "text": "購買價格，"}, {"start": 19.076333, "end": 20.94475, "text": "除以基礎直播課堂數，"}, {"start": 20.94475, "end": 23.247375, "text": "再乘以剩餘堂數。"}, {"start": 23.247375, "end": 26.168416, "text": "我們用假設數字看一次。"}, {"start": 26.168416, "end": 28.747375, "text": "假設購買價格是一萬二千元，"}, {"start": 28.747375, "end": 30.602625, "text": "基礎直播課共四十堂，"}, {"start": 30.602625, "end": 32.721041, "text": "剩下三十堂。"}, {"start": 32.721041, "end": 35.076333, "text": "先用一萬二千除以四十，"}, {"start": 35.076333, "end": 37.457875, "text": "得到每堂三百元。"}, {"start": 37.457875, "end": 39.247375, "text": "再乘以剩餘三十堂，"}, {"start": 39.247375, "end": 41.971041, "text": "退費金額是九千元。"}, {"start": 41.971041, "end": 43.615791, "text": "這只是計算示例，"}, {"start": 43.615791, "end": 46.326333, "text": "不是實際課包或售價。"}, {"start": 46.326333, "end": 49.957875, "text": "實際說明要使用該筆訂單的資料。"}, {"start": 49.957875, "end": 50.747375, "text": "第三，"}, {"start": 50.747375, "end": 53.313166, "text": "退款會在七到十四個工作天內，"}, {"start": 53.313166, "end": 55.668416, "text": "退回原付款管道。"}, {"start": 55.668416, "end": 57.786833, "text": "工作天不能說成日曆天，"}, {"start": 57.786833, "end": 61.1, "text": "也不要自行承諾隔天入帳。"}], "beats": [{"start": 0, "title": "第 4 堂仍在全額退費範圍", "detail": ""}, {"start": 14.260541, "title": "超過 4 堂：按公式計算", "detail": ""}, {"start": 23.247375, "title": "假設計算示例", "detail": ""}, {"start": 49.957875, "title": "7–14 個工作日 · 原付款方式", "detail": ""}], "alignment": 1.0}, {"id": "N15", "title": "哪些直接說，哪些要確認", "module": 6, "voice": "把這一單元放回實際工作。家長問已確認的授課語言、設備、體驗課服務或退費政策，你可以直接說明，不用每個問題都轉給顧問。如果家長問當期課包總價、指定贈品或未確認的服務細節，就先核對最新方案。如果問孩子應該上哪個階段、未來怎麼安排，就記下問題，再由相關老師進一步了解。例如，家長說孩子不愛開口，你可以記錄他的具體描述，邀請他在體驗中觀察孩子的參與。不能直接說孩子一定需要哪個階段，也不能保證上課後就會變得外向。好的產品說明，是資訊清楚、條件完整。既讓家長得到答案，也不把未確認的事情講成承諾。", "paragraphs": ["把這一單元放回實際工作。家長問已確認的授課語言、設備、體驗課服務或退費政策，你可以直接說明，不用每個問題都轉給顧問。", "如果家長問當期課包總價、指定贈品或未確認的服務細節，就先核對最新方案。如果問孩子應該上哪個階段、未來怎麼安排，就記下問題，再由相關老師進一步了解。", "例如，家長說孩子不愛開口，你可以記錄他的具體描述，邀請他在體驗中觀察孩子的參與。不能直接說孩子一定需要哪個階段，也不能保證上課後就會變得外向。", "好的產品說明，是資訊清楚、條件完整。既讓家長得到答案，也不把未確認的事情講成承諾。"], "duration": 52.3, "cues": [{"start": 0.1, "end": 3.221041, "text": "把這一單元放回實際工作。"}, {"start": 3.221041, "end": 5.457875, "text": "家長問已確認的授課語言、"}, {"start": 5.457875, "end": 8.44475, "text": "設備、體驗課服務或退費政策，"}, {"start": 8.44475, "end": 9.878958, "text": "你可以直接說明，"}, {"start": 9.878958, "end": 12.813166, "text": "不用每個問題都轉給顧問。"}, {"start": 12.813166, "end": 14.997375, "text": "如果家長問當期課包總價、"}, {"start": 14.997375, "end": 17.536833, "text": "指定贈品或未確認的服務細節，"}, {"start": 17.536833, "end": 20.05, "text": "就先核對最新方案。"}, {"start": 20.05, "end": 23.734208, "text": "如果問孩子應該上哪個階段、未來怎麼安排，"}, {"start": 23.734208, "end": 25.036833, "text": "就記下問題，"}, {"start": 25.036833, "end": 27.94475, "text": "再由相關老師進一步了解。"}, {"start": 27.94475, "end": 28.760541, "text": "例如，"}, {"start": 28.760541, "end": 30.668416, "text": "家長說孩子不愛開口，"}, {"start": 30.668416, "end": 32.760541, "text": "你可以記錄他的具體描述，"}, {"start": 32.760541, "end": 36.010541, "text": "邀請他在體驗中觀察孩子的參與。"}, {"start": 36.010541, "end": 38.747375, "text": "不能直接說孩子一定需要哪個階段，"}, {"start": 38.747375, "end": 42.115791, "text": "也不能保證上課後就會變得外向。"}, {"start": 42.115791, "end": 43.628958, "text": "好的產品說明，"}, {"start": 43.628958, "end": 46.865791, "text": "是資訊清楚、條件完整。"}, {"start": 46.865791, "end": 48.615791, "text": "既讓家長得到答案，"}, {"start": 48.615791, "end": 52.3, "text": "也不把未確認的事情講成承諾。"}], "beats": [{"start": 0, "title": "已確認資訊可直接說", "detail": ""}, {"start": 12.813166, "title": "活動核對、個別規劃交接", "detail": ""}, {"start": 27.94475, "title": "不憑描述直接定階", "detail": ""}, {"start": 42.115791, "title": "資訊清楚，條件完整", "detail": ""}], "alignment": 1.0}, {"id": "N17", "title": "產品知識診斷怎麼做", "module": 7, "voice": "接下來是產品知識診斷。共有二十道知識題，每題五分，滿分一百分。另外有兩道理解情境題，請用自己的話解釋，不用寫成完整電話話術。單選題選一個答案。多選題要全部選對，而且不能多選，這題才得分。第一次請獨立完成，先不查資料，這樣才能看出原本的理解。兩道情境題分別檢查課程價值與體驗安排。重點是資訊準確、條件完整，以及能分清楚哪些需要確認。這一階段不評電話開場、邀約技巧或說話是否流利。完成後，查看首次分數、需要複習的主題和自己的回答。八十分是初步理解的參考，還要由培訓師透過答疑確認。複習後可以重測，首次紀錄會保留。", "paragraphs": ["接下來是產品知識診斷。共有二十道知識題，每題五分，滿分一百分。另外有兩道理解情境題，請用自己的話解釋，不用寫成完整電話話術。", "單選題選一個答案。多選題要全部選對，而且不能多選，這題才得分。第一次請獨立完成，先不查資料，這樣才能看出原本的理解。", "兩道情境題分別檢查課程價值與體驗安排。重點是資訊準確、條件完整，以及能分清楚哪些需要確認。這一階段不評電話開場、邀約技巧或說話是否流利。", "完成後，查看首次分數、需要複習的主題和自己的回答。八十分是初步理解的參考，還要由培訓師透過答疑確認。複習後可以重測，首次紀錄會保留。"], "duration": 59.7, "cues": [{"start": 0.1, "end": 3.19475, "text": "接下來是產品知識診斷。"}, {"start": 3.19475, "end": 4.957875, "text": "共有二十道知識題，"}, {"start": 4.957875, "end": 6.010541, "text": "每題五分，"}, {"start": 6.010541, "end": 7.931583, "text": "滿分一百分。"}, {"start": 7.931583, "end": 10.010541, "text": "另外有兩道理解情境題，"}, {"start": 10.010541, "end": 11.721041, "text": "請用自己的話解釋，"}, {"start": 11.721041, "end": 14.497375, "text": "不用寫成完整電話話術。"}, {"start": 14.497375, "end": 17.089458, "text": "單選題選一個答案。"}, {"start": 17.089458, "end": 18.94475, "text": "多選題要全部選對，"}, {"start": 18.94475, "end": 20.339458, "text": "而且不能多選，"}, {"start": 20.339458, "end": 22.221041, "text": "這題才得分。"}, {"start": 22.221041, "end": 23.971041, "text": "第一次請獨立完成，"}, {"start": 23.971041, "end": 25.260541, "text": "先不查資料，"}, {"start": 25.260541, "end": 27.997375, "text": "這樣才能看出原本的理解。"}, {"start": 27.997375, "end": 32.40525, "text": "兩道情境題分別檢查課程價值與體驗安排。"}, {"start": 32.40525, "end": 35.431583, "text": "重點是資訊準確、條件完整，"}, {"start": 35.431583, "end": 38.471041, "text": "以及能分清楚哪些需要確認。"}, {"start": 38.471041, "end": 43.602625, "text": "這一階段不評電話開場、邀約技巧或說話是否流利。"}, {"start": 43.602625, "end": 44.628958, "text": "完成後，"}, {"start": 44.628958, "end": 49.457875, "text": "查看首次分數、需要複習的主題和自己的回答。"}, {"start": 49.457875, "end": 51.786833, "text": "八十分是初步理解的參考，"}, {"start": 51.786833, "end": 54.971041, "text": "還要由培訓師透過答疑確認。"}, {"start": 54.971041, "end": 56.747375, "text": "複習後可以重測，"}, {"start": 56.747375, "end": 59.7, "text": "首次紀錄會保留。"}], "beats": [{"start": 0, "title": "20 道知識題＋2 道理解情境題", "detail": ""}, {"start": 14.497375, "title": "首次獨立作答", "detail": ""}, {"start": 27.997375, "title": "檢查產品理解，不考電話技巧", "detail": ""}, {"start": 43.602625, "title": "保留首次紀錄，複習後可重測", "detail": ""}], "alignment": 1.0}, {"id": "N18", "title": "把學習回報發到培訓群", "module": 7, "voice": "測試完成後，還有最後一步。請在結果頁檢查學習回報，把姓名、首次和最近成績、情境回答，以及仍有疑問的地方整理清楚。頁面會幫你整理文字，你可以補充自己的話，再按複製學習回報。接著切換到培訓群，貼上並傳送。複製成功不代表老師已經收到，這個頁面不會自動發送資料。參加答疑時，請帶著學員學習手冊。培訓師會根據大家的回答追問，幫你分清容易混淆的產品資訊。你可以把修正後的理解記回學習單。這門課先建立產品知識基礎。各階段體驗課的具體內容、約課流程和電話技巧，會在後續專項培訓接著學習。", "paragraphs": ["測試完成後，還有最後一步。請在結果頁檢查學習回報，把姓名、首次和最近成績、情境回答，以及仍有疑問的地方整理清楚。", "頁面會幫你整理文字，你可以補充自己的話，再按複製學習回報。接著切換到培訓群，貼上並傳送。複製成功不代表老師已經收到，這個頁面不會自動發送資料。", "參加答疑時，請帶著學員學習手冊。培訓師會根據大家的回答追問，幫你分清容易混淆的產品資訊。你可以把修正後的理解記回學習單。", "這門課先建立產品知識基礎。各階段體驗課的具體內容、約課流程和電話技巧，會在後續專項培訓接著學習。"], "duration": 53.3, "cues": [{"start": 0.1, "end": 1.428958, "text": "測試完成後，"}, {"start": 1.428958, "end": 3.563166, "text": "還有最後一步。"}, {"start": 3.563166, "end": 5.734208, "text": "請在結果頁檢查學習回報，"}, {"start": 5.734208, "end": 9.44475, "text": "把姓名、首次和最近成績、情境回答，"}, {"start": 9.44475, "end": 12.44475, "text": "以及仍有疑問的地方整理清楚。"}, {"start": 12.44475, "end": 14.431583, "text": "頁面會幫你整理文字，"}, {"start": 14.431583, "end": 16.115791, "text": "你可以補充自己的話，"}, {"start": 16.115791, "end": 18.589458, "text": "再按複製學習回報。"}, {"start": 18.589458, "end": 20.576333, "text": "接著切換到培訓群，"}, {"start": 20.576333, "end": 22.734208, "text": "貼上並傳送。"}, {"start": 22.734208, "end": 25.339458, "text": "複製成功不代表老師已經收到，"}, {"start": 25.339458, "end": 28.44475, "text": "這個頁面不會自動發送資料。"}, {"start": 28.44475, "end": 29.8, "text": "參加答疑時，"}, {"start": 29.8, "end": 32.615791, "text": "請帶著學員學習手冊。"}, {"start": 32.615791, "end": 35.286833, "text": "培訓師會根據大家的回答追問，"}, {"start": 35.286833, "end": 38.497375, "text": "幫你分清容易混淆的產品資訊。"}, {"start": 38.497375, "end": 42.089458, "text": "你可以把修正後的理解記回學習單。"}, {"start": 42.089458, "end": 45.536833, "text": "這門課先建立產品知識基礎。"}, {"start": 45.536833, "end": 49.615791, "text": "各階段體驗課的具體內容、約課流程和電話技巧，"}, {"start": 49.615791, "end": 53.3, "text": "會在後續專項培訓接著學習。"}], "beats": [{"start": 0, "title": "先整理學習回報", "detail": ""}, {"start": 12.44475, "title": "複製後自行貼到培訓群", "detail": ""}, {"start": 28.44475, "title": "帶學習單參加答疑", "detail": ""}, {"start": 42.089458, "title": "後續再學體驗內容、約課與電話", "detail": ""}], "alignment": 1.0}, {"id": "N20", "title": "幼兒階段學什麼？與國小如何銜接", "module": 2, "voice": "幼兒階段學什麼？重點是從孩子熟悉的數量、圖形與生活情境出發，練習觀察、比較和表達。不是把國小的計算題直接提前教給孩子。五類內容可以這樣理解。數與代數，觀察數量和多寡。空間幾何，觀察形狀和位置，透過拼搭理解空間。邏輯與推理，找規律和線索，說出判斷理由。生活應用，從分類、時間和測量連結生活。益智策略，在任務中試不同做法，比較不同選擇。舉個幫助理解的例子，把紅色和黃色的積木分開，再試著按照紅、黃、紅、黃排下去。老師可以問，下一個放哪個顏色？你怎麼知道？重點不只是排對，而是讓孩子觀察規律，試著說出理由。這是教學說明例子，不代表指定階段一定使用這道題。和國小階段比較，幼兒階段從熟悉的具體情境練習觀察、比較和表達。國小階段則進一步整理條件、選擇方法，再說明理由，並嘗試運用到問題中。這是培養方向的比較，不是只憑年齡直接配階。個別適合哪一階，仍需了解學習情況後確認。", "paragraphs": ["幼兒階段學什麼？重點是從孩子熟悉的數量、圖形與生活情境出發，練習觀察、比較和表達。不是把國小的計算題直接提前教給孩子。", "五類內容可以這樣理解。數與代數，觀察數量和多寡。空間幾何，觀察形狀和位置，透過拼搭理解空間。邏輯與推理，找規律和線索，說出判斷理由。生活應用，從分類、時間和測量連結生活。益智策略，在任務中試不同做法，比較不同選擇。", "舉個幫助理解的例子，把紅色和黃色的積木分開，再試著按照紅、黃、紅、黃排下去。老師可以問，下一個放哪個顏色？你怎麼知道？重點不只是排對，而是讓孩子觀察規律，試著說出理由。這是教學說明例子，不代表指定階段一定使用這道題。", "和國小階段比較，幼兒階段從熟悉的具體情境練習觀察、比較和表達。國小階段則進一步整理條件、選擇方法，再說明理由，並嘗試運用到問題中。這是培養方向的比較，不是只憑年齡直接配階。個別適合哪一階，仍需了解學習情況後確認。"], "duration": 90.0, "cues": [{"start": 0.1, "end": 2.484208, "text": "幼兒階段學什麼？"}, {"start": 2.484208, "end": 6.642125, "text": "重點是從孩子熟悉的數量、圖形與生活情境出發，"}, {"start": 6.642125, "end": 9.839458, "text": "練習觀察、比較和表達。"}, {"start": 9.839458, "end": 14.063166, "text": "不是把國小的計算題直接提前教給孩子。"}, {"start": 14.063166, "end": 16.839458, "text": "五類內容可以這樣理解。"}, {"start": 16.839458, "end": 18.089458, "text": "數與代數，"}, {"start": 18.089458, "end": 20.523666, "text": "觀察數量和多寡。"}, {"start": 20.523666, "end": 21.668416, "text": "空間幾何，"}, {"start": 21.668416, "end": 23.313166, "text": "觀察形狀和位置，"}, {"start": 23.313166, "end": 25.69475, "text": "透過拼搭理解空間。"}, {"start": 25.69475, "end": 27.036833, "text": "邏輯與推理，"}, {"start": 27.036833, "end": 28.510541, "text": "找規律和線索，"}, {"start": 28.510541, "end": 30.773666, "text": "說出判斷理由。"}, {"start": 30.773666, "end": 32.023666, "text": "生活應用，"}, {"start": 32.023666, "end": 36.010541, "text": "從分類、時間和測量連結生活。"}, {"start": 36.010541, "end": 37.207875, "text": "益智策略，"}, {"start": 37.207875, "end": 39.102625, "text": "在任務中試不同做法，"}, {"start": 39.102625, "end": 41.365791, "text": "比較不同選擇。"}, {"start": 41.365791, "end": 43.207875, "text": "舉個幫助理解的例子，"}, {"start": 43.207875, "end": 45.247375, "text": "把紅色和黃色的積木分開，"}, {"start": 45.247375, "end": 49.497375, "text": "再試著按照紅、黃、紅、黃排下去。"}, {"start": 49.497375, "end": 50.839458, "text": "老師可以問，"}, {"start": 50.839458, "end": 53.181583, "text": "下一個放哪個顏色？"}, {"start": 53.181583, "end": 55.181583, "text": "你怎麼知道？"}, {"start": 55.181583, "end": 56.892125, "text": "重點不只是排對，"}, {"start": 56.892125, "end": 58.668416, "text": "而是讓孩子觀察規律，"}, {"start": 58.668416, "end": 60.918416, "text": "試著說出理由。"}, {"start": 60.918416, "end": 62.668416, "text": "這是教學說明例子，"}, {"start": 62.668416, "end": 66.089458, "text": "不代表指定階段一定使用這道題。"}, {"start": 66.089458, "end": 67.90525, "text": "和國小階段比較，"}, {"start": 67.90525, "end": 73.063166, "text": "幼兒階段從熟悉的具體情境練習觀察、比較和表達。"}, {"start": 73.063166, "end": 76.628958, "text": "國小階段則進一步整理條件、選擇方法，"}, {"start": 76.628958, "end": 77.826333, "text": "再說明理由，"}, {"start": 77.826333, "end": 80.247375, "text": "並嘗試運用到問題中。"}, {"start": 80.247375, "end": 82.128958, "text": "這是培養方向的比較，"}, {"start": 82.128958, "end": 84.931583, "text": "不是只憑年齡直接配階。"}, {"start": 84.931583, "end": 86.418416, "text": "個別適合哪一階，"}, {"start": 86.418416, "end": 90.0, "text": "仍需了解學習情況後確認。"}], "beats": [{"start": 0, "title": "幼兒：從熟悉的具體情境出發", "detail": ""}, {"start": 14.063166, "title": "幼兒階段的五類內容", "detail": ""}, {"start": 41.365791, "title": "分類與規律：試著說出理由", "detail": ""}, {"start": 66.089458, "title": "幼兒與國小的培養方向", "detail": ""}], "alignment": 1.0}, {"id": "N21", "module": 5, "title": "教材複習與學、練、測、評", "voice": "想再操作課堂教材，應找教材複習。它和重看當堂師生互動的課程回放不同，也和快速整理概念的重點回顧影片不同。先問家長想做什麼，再選資源。把課前到課後連起來，可以用學、練、測、評來理解。學，是透過預習與課堂互動接觸內容。練，是再做練習，或透過小老師影片說出做法。測，是利用專題與階段練習觀察理解。評，是結合課堂表現、練習與學習回饋，了解需要協助的地方。延伸練習則讓孩子在不同情境嘗試運用已學內容。例如，先理解一種分配方法，再看看換成其他物品時會怎麼做。這是說明練習用途，不代表做完題目就保證掌握，也不把這些練習說成專業能力診斷。各項資源的開通與期限，仍依實際方案確認。", "paragraphs": ["想再操作課堂教材，應找教材複習。它和重看當堂師生互動的課程回放不同，也和快速整理概念的重點回顧影片不同。先問家長想做什麼，再選資源。", "把課前到課後連起來，可以用學、練、測、評來理解。學，是透過預習與課堂互動接觸內容。練，是再做練習，或透過小老師影片說出做法。測，是利用專題與階段練習觀察理解。評，是結合課堂表現、練習與學習回饋，了解需要協助的地方。", "延伸練習則讓孩子在不同情境嘗試運用已學內容。例如，先理解一種分配方法，再看看換成其他物品時會怎麼做。這是說明練習用途，不代表做完題目就保證掌握，也不把這些練習說成專業能力診斷。各項資源的開通與期限，仍依實際方案確認。"], "duration": 66.0, "cues": [{"start": 0.1, "end": 2.126333, "text": "想再操作課堂教材，"}, {"start": 2.126333, "end": 4.497375, "text": "應找教材複習。"}, {"start": 4.497375, "end": 7.826333, "text": "它和重看當堂師生互動的課程回放不同，"}, {"start": 7.826333, "end": 11.668416, "text": "也和快速整理概念的重點回顧影片不同。"}, {"start": 11.668416, "end": 13.497375, "text": "先問家長想做什麼，"}, {"start": 13.497375, "end": 15.497375, "text": "再選資源。"}, {"start": 15.497375, "end": 17.484208, "text": "把課前到課後連起來，"}, {"start": 17.484208, "end": 21.536833, "text": "可以用學、練、測、評來理解。"}, {"start": 21.536833, "end": 22.273666, "text": "學，"}, {"start": 22.273666, "end": 25.984208, "text": "是透過預習與課堂互動接觸內容。"}, {"start": 25.984208, "end": 26.734208, "text": "練，"}, {"start": 26.734208, "end": 28.063166, "text": "是再做練習，"}, {"start": 28.063166, "end": 31.286833, "text": "或透過小老師影片說出做法。"}, {"start": 31.286833, "end": 32.207875, "text": "測，"}, {"start": 32.207875, "end": 35.813166, "text": "是利用專題與階段練習觀察理解。"}, {"start": 35.813166, "end": 36.497375, "text": "評，"}, {"start": 36.497375, "end": 39.878958, "text": "是結合課堂表現、練習與學習回饋，"}, {"start": 39.878958, "end": 42.273666, "text": "了解需要協助的地方。"}, {"start": 42.273666, "end": 47.221041, "text": "延伸練習則讓孩子在不同情境嘗試運用已學內容。"}, {"start": 47.221041, "end": 47.997375, "text": "例如，"}, {"start": 47.997375, "end": 49.865791, "text": "先理解一種分配方法，"}, {"start": 49.865791, "end": 53.3, "text": "再看看換成其他物品時會怎麼做。"}, {"start": 53.3, "end": 55.036833, "text": "這是說明練習用途，"}, {"start": 55.036833, "end": 57.378958, "text": "不代表做完題目就保證掌握，"}, {"start": 57.378958, "end": 60.839458, "text": "也不把這些練習說成專業能力診斷。"}, {"start": 60.839458, "end": 62.984208, "text": "各項資源的開通與期限，"}, {"start": 62.984208, "end": 66.0, "text": "仍依實際方案確認。"}], "beats": [{"start": 0, "title": "先分清教材複習、回放與重點影片", "detail": ""}, {"start": 15.497375, "title": "學 → 練 → 測 → 評", "detail": ""}, {"start": 42.273666, "title": "延伸練習：換情境，試著運用", "detail": ""}], "alignment": 1.0}, {"id": "N22", "module": 2, "title": "九階不只安排內容，也培養學習習慣", "voice": "九階架構除了安排數學內容，也呈現思考、習慣和情感三個培養面向。思考，是練習分類、對應、推理等方法。習慣，是練習動手嘗試、認真聽講、主動思考和表達。情感，是從自我認知、情緒表達，逐步接觸合作分享等方向。這些是課程設計的方向，不是每個孩子完成某一階，就一定達成所有表現。對TMK來說，要能說明課程不只看答案，也關注孩子怎麼參與、怎麼想、怎麼表達。具體學習情況仍要結合老師回饋，個別適合哪一階也需進一步確認。", "paragraphs": ["九階架構除了安排數學內容，也呈現思考、習慣和情感三個培養面向。思考，是練習分類、對應、推理等方法。習慣，是練習動手嘗試、認真聽講、主動思考和表達。情感，是從自我認知、情緒表達，逐步接觸合作分享等方向。", "這些是課程設計的方向，不是每個孩子完成某一階，就一定達成所有表現。對TMK來說，要能說明課程不只看答案，也關注孩子怎麼參與、怎麼想、怎麼表達。具體學習情況仍要結合老師回饋，個別適合哪一階也需進一步確認。"], "duration": 46.0, "cues": [{"start": 0.1, "end": 2.573666, "text": "九階架構除了安排數學內容，"}, {"start": 2.573666, "end": 6.984208, "text": "也呈現思考、習慣和情感三個培養面向。"}, {"start": 6.984208, "end": 7.918416, "text": "思考，"}, {"start": 7.918416, "end": 11.971041, "text": "是練習分類、對應、推理等方法。"}, {"start": 11.971041, "end": 12.94475, "text": "習慣，"}, {"start": 12.94475, "end": 18.378958, "text": "是練習動手嘗試、認真聽講、主動思考和表達。"}, {"start": 18.378958, "end": 19.339458, "text": "情感，"}, {"start": 19.339458, "end": 21.813166, "text": "是從自我認知、情緒表達，"}, {"start": 21.813166, "end": 24.813166, "text": "逐步接觸合作分享等方向。"}, {"start": 24.813166, "end": 26.918416, "text": "這些是課程設計的方向，"}, {"start": 26.918416, "end": 28.786833, "text": "不是每個孩子完成某一階，"}, {"start": 28.786833, "end": 31.44475, "text": "就一定達成所有表現。"}, {"start": 31.44475, "end": 32.721041, "text": "對TMK來說，"}, {"start": 32.721041, "end": 34.865791, "text": "要能說明課程不只看答案，"}, {"start": 34.865791, "end": 39.313166, "text": "也關注孩子怎麼參與、怎麼想、怎麼表達。"}, {"start": 39.313166, "end": 42.207875, "text": "具體學習情況仍要結合老師回饋，"}, {"start": 42.207875, "end": 46.0, "text": "個別適合哪一階也需進一步確認。"}], "beats": [{"start": 0, "title": "思考、習慣、情感三個面向", "detail": ""}, {"start": 24.813166, "title": "培養方向，不是每階成效保證", "detail": ""}], "alignment": 1.0}], "questions": [{"id": 1, "title": "課程定位〔單選〕", "prompt": "家長想知道課程主要做什麼，哪個說法最準確？", "options": [{"label": "A", "text": "由真人老師帶領孩子觀察問題、嘗試方法並說明理由。"}, {"label": "B", "text": "只要重複看影片，就能保證理解所有內容。"}, {"label": "C", "text": "每堂都完全配合校內進度，不需再確認。"}], "correct": ["A"], "module": 1, "multi": false, "priority": false}, {"id": 2, "title": "班型資訊〔單選〕", "prompt": "關於 S2 正式課，哪項正確？", "options": [{"label": "A", "text": "6–8 人，每堂 30–35 分鐘。"}, {"label": "B", "text": "4–6 人，每堂 40–45 分鐘，每週 2 次。"}, {"label": "C", "text": "4–6 人，每堂 30–35 分鐘，每週 1 次。"}], "correct": ["B"], "module": 3, "multi": false, "priority": false}, {"id": 3, "title": "小舞臺〔單選〕", "prompt": "同學何時能看到、聽到受邀孩子？", "options": [{"label": "A", "text": "從登入起，整堂課都能。"}, {"label": "B", "text": "只要是小班，就一直互相看到。"}, {"label": "C", "text": "老師邀請孩子上小舞臺分享時。"}], "correct": ["C"], "module": 3, "multi": false, "priority": true}, {"id": 4, "title": "體驗人數〔單選〕", "prompt": "家長問明天一定有幾個孩子，你應如何處理？", "options": [{"label": "A", "text": "依所選階段、時段及當天報名情況確認，不保證固定人數。"}, {"label": "B", "text": "直接用正式課人數保證。"}, {"label": "C", "text": "體驗一定是一對一。"}], "correct": ["A"], "module": 4, "multi": false, "priority": true}, {"id": 5, "title": "語言、設備與準備〔多選〕", "prompt": "哪些說法符合教材？", "options": [{"label": "A", "text": "中文授課搭配繁體課件，英文授課搭配英文課件。"}, {"label": "B", "text": "手機、平板、筆電皆可使用，課前確認 VIPThink 學生端帳號與登入。"}, {"label": "C", "text": "臺灣專屬師資代表每位教師一定都是臺灣人。"}, {"label": "D", "text": "建議家長陪同體驗，觀察孩子參與情況。"}], "correct": ["A", "B", "D"], "module": 4, "multi": true, "priority": true}, {"id": 6, "title": "回放〔單選〕", "prompt": "家長想重看體驗當天的師生互動，哪項說明適合？", "options": [{"label": "A", "text": "看小老師影片，就能看到整堂實際互動。"}, {"label": "B", "text": "可以看體驗課回放，有效期 180 天；其他資源依實際方案說明。"}, {"label": "C", "text": "所有課程資源一律有效 180 天。"}], "correct": ["B"], "module": 5, "multi": false, "priority": true}, {"id": 7, "title": "練習與服務〔多選〕", "prompt": "哪些說法正確？", "options": [{"label": "A", "text": "體驗課線上鞏固練習對應 3 個環節，每環節 2 題，約 6 題。"}, {"label": "B", "text": "小老師影片提供孩子說明做法的機會。"}, {"label": "C", "text": "三師服務代表三位老師全程一對一陪上課。"}, {"label": "D", "text": "班導師主要負責課程聯繫、學習追蹤與回饋。"}], "correct": ["A", "B", "D"], "module": 5, "multi": true, "priority": false}, {"id": 8, "title": "第 4 堂〔單選〕", "prompt": "完成第 4 堂後申請退費，依教材適用哪一項？", "options": [{"label": "A", "text": "已超過 4 堂，只能依剩餘堂數計算。"}, {"label": "B", "text": "不得退費。"}, {"label": "C", "text": "4 堂以內含第 4 堂，可以申請全額退費。"}], "correct": ["C"], "module": 6, "multi": false, "priority": true}, {"id": 9, "title": "超過 4 堂〔單選〕", "prompt": "哪一項完整符合教材？", "options": [{"label": "A", "text": "購買價格 ÷ 基礎直播課總堂數 × 剩餘堂數；7–14 個工作日內，退回原付款方式。"}, {"label": "B", "text": "購買價格 ÷ 剩餘堂數；7–14 個日曆天內，任選退款帳戶。"}, {"label": "C", "text": "一律全額退費，當天入帳。"}], "correct": ["A"], "module": 6, "multi": false, "priority": true}, {"id": 10, "title": "個別規劃〔單選〕", "prompt": "家長問：「六歲一定是哪一階？幾堂會進步？」最適合的處理是？", "options": [{"label": "A", "text": "只看年齡定階，保證四堂有效。"}, {"label": "B", "text": "了解學習情況，再由評估或規劃人員確認，不保證進步時間。"}, {"label": "C", "text": "所有產品資訊都不能回答，直接結束對話。"}], "correct": ["B"], "module": 6, "multi": false, "priority": false}, {"id": 11, "title": "課程內容〔單選〕", "prompt": "「拼搭、分割與變換」主要對應哪一類內容？", "options": [{"label": "A", "text": "空間幾何。"}, {"label": "B", "text": "只有加減計算。"}, {"label": "C", "text": "課程退費安排。"}], "correct": ["A"], "module": 2, "multi": false, "priority": false}, {"id": 12, "title": "九階安排〔單選〕", "prompt": "九階課程主要表達什麼？", "options": [{"label": "A", "text": "每個年齡只能上固定一階，無須了解學習情況。"}, {"label": "B", "text": "所有階段內容完全相同。"}, {"label": "C", "text": "內容有前後安排，個別適合階段需進一步了解。"}], "correct": ["C"], "module": 2, "multi": false, "priority": false}, {"id": 13, "title": "教學設計〔多選〕", "prompt": "哪些說法符合課堂設計的用意？", "options": [{"label": "A", "text": "故事帶出任務，讓孩子有問題可思考。"}, {"label": "B", "text": "圖片和操作幫助孩子觀察關係、理解問題。"}, {"label": "C", "text": "老師提問，讓孩子嘗試說明做法與理由。"}, {"label": "D", "text": "TMK 必須能完整教授 CPA 和 6E 的教學步驟。"}], "correct": ["A", "B", "C"], "module": 2, "multi": true, "priority": false}, {"id": 14, "title": "其他正式課規格〔單選〕", "prompt": "哪一組配對正確？", "options": [{"label": "A", "text": "S1 為 6–8 人，40–45 分鐘；S3–S9 為 4–6 人，30–35 分鐘。"}, {"label": "B", "text": "S1 為 4–6 人，30–35 分鐘；S3–S9 為 6–8 人，40–45 分鐘。"}, {"label": "C", "text": "所有正式課人數和時間都相同。"}], "correct": ["B"], "module": 3, "multi": false, "priority": false}, {"id": 15, "title": "陪同體驗〔單選〕", "prompt": "建議家長陪同的主要目的是什麼？", "options": [{"label": "A", "text": "了解課程並觀察孩子參與情況。"}, {"label": "B", "text": "由家長替孩子回答，確保全部答對。"}, {"label": "C", "text": "沒有家長陪同就保證無法上課。"}], "correct": ["A"], "module": 4, "multi": false, "priority": false}, {"id": 16, "title": "複習資源〔單選〕", "prompt": "家長想「再操作教材」及「快速整理主要概念」，依序應使用什麼？", "options": [{"label": "A", "text": "課程回放、小老師影片。"}, {"label": "B", "text": "重點回顧影片、教材複習。"}, {"label": "C", "text": "教材複習、重點回顧影片。"}], "correct": ["C"], "module": 5, "multi": false, "priority": false}, {"id": 17, "title": "服務角色〔單選〕", "prompt": "哪項分工正確？", "options": [{"label": "A", "text": "教研支援負責每次幫孩子代答。"}, {"label": "B", "text": "授課老師負責課堂引導與觀察；教研支援負責課程內容、路徑與教學支持。"}, {"label": "C", "text": "班導師取代所有授課老師。"}], "correct": ["B"], "module": 5, "multi": false, "priority": false}, {"id": 18, "title": "學習觀察〔多選〕", "prompt": "哪些資訊應綜合參考？", "options": [{"label": "A", "text": "孩子是否嘗試、如何回應。"}, {"label": "B", "text": "課後練習、做法與理由。"}, {"label": "C", "text": "老師的學習回饋。"}, {"label": "D", "text": "只要孩子開心，就能判定完全理解。"}], "correct": ["A", "B", "C"], "module": 5, "multi": true, "priority": false}, {"id": 19, "title": "退費計算〔單選〕", "prompt": "假設已超過 4 堂，購買價格 8,000 元，基礎直播課共 20 堂，剩餘 10 堂，依公式退費多少？本題為練習假設，非實際售價。", "options": [{"label": "A", "text": "8,000 元。"}, {"label": "B", "text": "400 元。"}, {"label": "C", "text": "4,000 元。"}], "correct": ["C"], "module": 6, "multi": false, "priority": true}, {"id": 20, "title": "學練測評〔單選〕", "prompt": "哪項理解最符合教材？", "options": [{"label": "A", "text": "預習與互動幫助學習，練習與表達幫助回顧，專題及階段練習提供觀察，再結合回饋了解需要協助處。"}, {"label": "B", "text": "預習影片直接取代真人直播。"}, {"label": "C", "text": "只看題量即可保證學習成果。"}], "correct": ["A"], "module": 5, "multi": false, "priority": false}], "voice": "雲哲｜臺灣華語男聲", "mediaRevision": "animated-v3", "release": "2026-11-05-reviewed"};